#!/usr/bin/env node
/**
 * Build the derived artifacts used by the EdgeOne function:
 *
 *   sentences/index.json      - per-category length histograms (debug/reference)
 *   lib/sentence-index.js     - the same index as a JS module
 *   lib/data/<category>.js    - gzip + base64 sentence data
 *   lib/data/index.js         - map of all compressed categories
 *
 * Sentence files are compressed with gzip + base64 so the edge function bundle
 * stays small. One category is decompressed per request. The gzip header uses
 * mtime=0, which keeps the generated files deterministic across machines and
 * CI runs.
 *
 * Usage:
 *   node scripts/build-index.mjs          # write generated files
 *   node scripts/build-index.mjs --check  # exit 1 when anything is stale
 */
import { createHash } from "node:crypto";
import { mkdir, readFile, readdir, unlink, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";
import { gzipSync } from "../lib/vendor/fflate.js";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const sentencesDir = path.join(root, "sentences");
const libDir = path.join(root, "lib");
const dataDir = path.join(libDir, "data");
const indexPath = path.join(sentencesDir, "index.json");
const checkOnly = process.argv.includes("--check");

const files = (await readdir(sentencesDir))
  .filter((name) => /^[a-z]\.json$/.test(name))
  .sort();

if (files.length === 0) {
  console.error("No sentences/<category>.json files found.");
  process.exit(1);
}

const categories = {};
const rawByKey = {};
let total = 0;

for (const file of files) {
  const key = path.basename(file, ".json");
  const raw = await readFile(path.join(sentencesDir, file), "utf8");
  const list = JSON.parse(raw);

  if (!Array.isArray(list)) {
    console.error(`${file} is not a JSON array.`);
    process.exit(1);
  }

  const lengths = {};
  let maxLength = 0;

  for (const sentence of list) {
    const rawLength = sentence?.length;
    const length = Number.isFinite(Number(rawLength))
      ? Number(rawLength)
      : String(sentence?.hitokoto ?? "").length;
    const bucket = Math.max(0, Math.trunc(length));
    lengths[bucket] = (lengths[bucket] || 0) + 1;
    if (bucket > maxLength) maxLength = bucket;
  }

  categories[key] = {
    count: list.length,
    maxLength,
    lengths,
  };
  rawByKey[key] = raw;
  total += list.length;
}

// Stable version derived from the actual data, so a data change is visible in
// the generated files and in deploys.
const version = createHash("sha256")
  .update(JSON.stringify({ total, categories }))
  .digest("hex")
  .slice(0, 12);

const index = { version, total, generatedBy: "scripts/build-index.mjs", categories };
const indexOutput = `${JSON.stringify(index, null, 2)}\n`;

// Node 24 requires an import attribute for JSON modules, and EdgeOne's builder
// does not need one.  A generated JS module keeps both toolchains happy and is
// still only ~15 KB in the function bundle.
const modulePath = path.join(libDir, "sentence-index.js");
const moduleOutput = `// Generated by scripts/build-index.mjs. Do not edit by hand.\nexport default ${JSON.stringify(
  index,
  null,
  2,
)};\n`;

// One module per category so the bundler can still tree-shake nothing (we need
// all of them for random selection), but the code stays readable and a diff of
// a single category is easy to inspect.
const dataOutputs = new Map();
for (const key of Object.keys(categories)) {
  const compressed = Buffer.from(
    gzipSync(new Uint8Array(Buffer.from(rawByKey[key], "utf8")), {
      level: 9,
      mtime: 0,
    }),
  ).toString("base64");
  dataOutputs.set(
    path.join(dataDir, `${key}.js`),
    `// Generated by scripts/build-index.mjs. Do not edit by hand.\nexport default ${JSON.stringify(
      compressed,
    )};\n`,
  );
}

const dataIndexPath = path.join(dataDir, "index.js");
const dataIndexOutput = `// Generated by scripts/build-index.mjs. Do not edit by hand.\n${Object.keys(
  categories,
)
  .map((key) => `import ${key} from "./${key}.js";`)
  .join("\n")}\n\nexport const compressedSentences = {\n${Object.keys(categories)
  .map((key) => `  ${key},`)
  .join("\n")}\n};\n`;

async function readIfExists(file) {
  try {
    return await readFile(file, "utf8");
  } catch {
    return "";
  }
}

async function checkAll() {
  const mismatches = [];

  if ((await readIfExists(indexPath)) !== indexOutput) {
    mismatches.push(path.relative(root, indexPath));
  }
  if ((await readIfExists(modulePath)) !== moduleOutput) {
    mismatches.push(path.relative(root, modulePath));
  }
  if ((await readIfExists(dataIndexPath)) !== dataIndexOutput) {
    mismatches.push(path.relative(root, dataIndexPath));
  }
  for (const [file, output] of dataOutputs) {
    if ((await readIfExists(file)) !== output) {
      mismatches.push(path.relative(root, file));
    }
  }

  // Generated data modules for categories that no longer exist.
  for (const name of await readdir(dataDir).catch(() => [])) {
    if (/^[a-z]\.js$/.test(name) && !categories[name[0]]) {
      mismatches.push(path.relative(root, path.join(dataDir, name)));
    }
  }

  if (mismatches.length > 0) {
    console.error(
      `Generated sentence artifacts are stale:\n  ${mismatches.join(
        "\n  ",
      )}\nRun: node scripts/build-index.mjs`,
    );
    process.exit(1);
  }

  console.log(
    `Generated sentence artifacts are up to date (version ${version}, ${total} sentences).`,
  );
}

async function writeAll() {
  await mkdir(dataDir, { recursive: true });

  await writeFile(indexPath, indexOutput);
  await writeFile(modulePath, moduleOutput);
  for (const [file, output] of dataOutputs) {
    await writeFile(file, output);
  }
  await writeFile(dataIndexPath, dataIndexOutput);

  // Remove generated modules for categories that disappeared upstream.
  for (const name of await readdir(dataDir)) {
    if (/^[a-z]\.js$/.test(name) && !categories[name[0]]) {
      await unlink(path.join(dataDir, name));
    }
  }

  console.log(
    `Wrote sentence index and compressed data (version ${version}, ${total} sentences, ${files.length} categories).`,
  );
}

if (checkOnly) {
  await checkAll();
} else {
  await writeAll();
}
